B.bv_=new A.u("\ubc14\ub85c \ubc1c\uc744 \ubed7\uc5b4 \uacf5\ub9cc \ub178\ub9b0\ub2e4","Stab for the ball immediately")
B.bwQ=new A.u("\ub4a4\ub97c \ubcf4\uc9c0 \uc54a\uace0 \ub4f1\uc744 \ub3cc\ub9b0\ub2e4","Turn away without seeing the play")
